from __future__ import annotations

import os
import shutil
import sys
from http.cookiejar import MozillaCookieJar
from pathlib import Path
from typing import NoReturn

from gpsync.config import Settings


def write_netscape_cookies(path: Path, cookies: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = [
        "# Netscape HTTP Cookie File",
        "# Generated by gpsync. Treat this file like a password.",
    ]
    for cookie in cookies:
        domain = cookie.get("domain") or ""
        if not _is_google_domain(domain):
            continue
        include_sub = "TRUE" if domain.startswith(".") else "FALSE"
        cookie_path = cookie.get("path") or "/"
        secure = "TRUE" if cookie.get("secure") else "FALSE"
        expires = cookie.get("expires")
        if expires is None or expires < 0:
            expires_s = "0"
        else:
            expires_s = str(int(expires))
        name = cookie.get("name") or ""
        value = cookie.get("value") or ""
        if not name:
            continue
        lines.append("\t".join([domain, include_sub, cookie_path, secure, expires_s, name, value]))
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    _restrict_private_file(path)


def _is_google_domain(domain: str) -> bool:
    host = domain.lstrip(".").lower()
    suffixes = (
        "google.com",
        "google.ru",
        "youtube.com",
        "googleusercontent.com",
        "gstatic.com",
        "ggpht.com",
    )
    return any(host == suffix or host.endswith("." + suffix) for suffix in suffixes)


def import_cookies_txt(source: Path, dest: Path) -> None:
    jar = MozillaCookieJar(str(source))
    jar.load(ignore_discard=True, ignore_expires=True)
    cookies = [
        {
            "domain": cookie.domain,
            "path": cookie.path,
            "secure": cookie.secure,
            "expires": cookie.expires,
            "name": cookie.name,
            "value": cookie.value,
        }
        for cookie in jar
    ]
    write_netscape_cookies(dest, cookies)


def _restrict_private_file(path: Path) -> None:
    try:
        os.chmod(path, 0o600)
    except OSError:
        pass


def clear_session_secrets(settings: Settings) -> list[Path]:
    """Delete cookies and the Chromium profile. Never touches SQLite or downloads."""
    protected = {
        settings.db_path.resolve(),
        settings.config_path.resolve(),
        settings.output_dir.resolve(),
        settings.data_dir.resolve(),
    }
    cookies = settings.cookies_path.resolve()
    if cookies in protected:
        raise RuntimeError(f"Refusing to delete protected path: {cookies}")
    profile = settings.browser_profile_dir.resolve()
    if profile in protected:
        raise RuntimeError(f"Refusing to delete protected path: {profile}")

    removed: list[Path] = []
    if settings.cookies_path.is_file():
        settings.cookies_path.unlink()
        removed.append(settings.cookies_path)
    if settings.browser_profile_dir.exists():
        shutil.rmtree(settings.browser_profile_dir)
        removed.append(settings.browser_profile_dir)
    return removed


def login_with_browser(settings: Settings, ready_file: Path | None = None) -> None:
    try:
        from playwright.sync_api import Error as PlaywrightError
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright is not installed. Run: pip install -e . && playwright install chromium"
        ) from exc

    _require_display()
    settings.ensure_dirs()
    profile_dir = settings.browser_profile_dir
    print("Opening Chromium. Log in to Google Photos in the window.")
    if ready_file is None:
        print("When you see your library at https://photos.google.com/, return here and press Enter.")
    else:
        print("Waiting for login confirmation from the controlling session.", flush=True)

    browser_proxy = None
    network = settings.data_dir / 'network.json'
    if network.exists():
        import json
        from urllib.parse import urlsplit, unquote
        network_settings = json.loads(network.read_text())
        url = urlsplit(network_settings.get('browser_proxy') or network_settings['proxy'])
        scheme = 'socks5' if url.scheme == 'socks5h' else url.scheme
        browser_proxy = {'server': f'{scheme}://{url.hostname}:{url.port}'}
        if url.username: browser_proxy['username'] = unquote(url.username)
        if url.password: browser_proxy['password'] = unquote(url.password)

    extension = settings.data_dir / 'extensions' / 'proxy-switcher'
    launch_args = ["--disable-blink-features=AutomationControlled"]
    if extension.is_dir():
        extension = extension.resolve()
        launch_args += [f"--disable-extensions-except={extension}", f"--load-extension={extension}"]
        browser_proxy = None

    with sync_playwright() as playwright:
        try:
            context = playwright.chromium.launch_persistent_context(
                user_data_dir=str(profile_dir),
                headless=False,
                channel=os.environ.get("GPSYNC_BROWSER_CHANNEL") or None,
                proxy=browser_proxy,
                viewport={"width": 1280, "height": 800},
                args=launch_args,
                ignore_default_args=["--disable-extensions"] if extension.is_dir() else None,
            )
        except PlaywrightError as exc:
            _reraise_playwright_launch_error(exc)
        if extension.is_dir():
            workers = context.service_workers
            worker = next((w for w in workers if "onnfghpihccifgojkpnnncpagjcdbjod" in w.url), None)
            if worker is None:
                worker = context.wait_for_event("serviceworker", timeout=30000)
            worker.evaluate("""async () => {
                const prefs = await chrome.storage.local.get(null);
                const imported = {value: {mode: 'fixed_servers', rules: {singleProxy: {scheme: 'socks5', host: '127.0.0.1', port: 1180}, bypassList: ['<local>']}}};
                const name = 'VLESS SOCKS';
                await chrome.storage.local.set({
                    profiles: [...new Set([...(prefs.profiles || []), name])],
                    ['profile.' + name]: imported,
                    'last-manual': name, 'startup-proxy': 'no'
                });
                const value = {mode: imported.value.mode, rules: imported.value.rules};
                await new Promise((resolve, reject) => chrome.proxy.settings.set({value, scope: 'regular'}, () => {
                    if (chrome.runtime.lastError) reject(new Error(chrome.runtime.lastError.message)); else resolve();
                }));
            }""")
            config = worker.evaluate("() => new Promise(resolve => chrome.proxy.settings.get({}, result => resolve(result.value)))")
            network = settings.data_dir / 'network.json'
            import json
            rules = config.get('rules', {})
            endpoint = rules.get('singleProxy') or rules.get('proxyForHttps') or rules.get('proxyForHttp')
            if not endpoint or endpoint.get('scheme') not in ('socks5', 'http', 'https'):
                raise RuntimeError('Imported proxy configuration is not supported by the scanner')
            scheme = 'socks5h' if endpoint['scheme'] == 'socks5' else endpoint['scheme']
            saved = json.loads(network.read_text()) if network.exists() else {}
            saved['browser_proxy'] = f"{scheme}://{endpoint['host']}:{endpoint['port']}"
            network.write_text(json.dumps(saved))
            print('Imported Chrome proxy profile selected: VLESS SOCKS', flush=True)
        page = context.pages[0] if context.pages else context.new_page()
        page.goto("https://photos.google.com/", wait_until="domcontentloaded")
        try:
            if ready_file is None:
                sys.stdin.readline()
            else:
                while not ready_file.exists():
                    if not context.pages:
                        raise RuntimeError("Login browser closed before confirmation")
                    context.pages[0].wait_for_timeout(1000)
                ready_file.unlink()
        except KeyboardInterrupt:
            context.close()
            raise
        cookies = context.cookies()
        write_netscape_cookies(settings.cookies_path, cookies)
        context.close()

    print(f"Saved cookies to {settings.cookies_path}")
    print("Keep this cookies.txt private. If downloads start failing with login errors, run login again.")


def _require_display() -> None:
    if not sys.platform.startswith("linux"):
        return
    if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
        return
    raise RuntimeError(
        "No graphical display found (DISPLAY / WAYLAND_DISPLAY are empty). "
        "gpsync login opens a Chromium window — run it from a desktop session, "
        "or import cookies from your browser instead:\n"
        "  gpsync login --cookies ~/Downloads/cookies.txt"
    )


def _reraise_playwright_launch_error(exc: BaseException) -> NoReturn:
    text = str(exc).lower()
    if any(
        marker in text
        for marker in (
            "host system is missing dependencies",
            "error while loading shared libraries",
            "libglib",
            "libnss3",
            "executable doesn't exist",
        )
    ):
        raise RuntimeError(
            "Chromium failed to start. Install the browser and, on Linux, its system libraries:\n"
            "  playwright install chromium\n"
            "  playwright install-deps chromium\n"
            "(install-deps usually needs sudo.) Then retry gpsync login."
        ) from exc
    raise exc
